#include<cstdio>
#include<cstdint>
using namespace std;

const int MAX_K = 1000; // Assuming a reasonable upper bound for K
int main() {
    int K;
    int64_t ans = 0; // Use int64_t for larger sums

    while (true) {
        ans = 0;
        cin >> K;
        if (K == 0) break;

        int totalNumbers = (K * (K - 1)) / 2; // Total numbers to read
        int c[MAX_K * (MAX_K - 1) / 2] = {0}; // Static allocation with a fixed size
        for (int i = 0; i < totalNumbers; i++) {
            cin >> c[i];
            ans += c[i];
        }

        ans /= (K - 1); // Maintain division logic
        cout << ans << endl;
    }
}

